package imagekit_test

import (
	"encoding/json"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/xantiagoma/xtandard-image/internal/errs"
	"github.com/xantiagoma/xtandard-image/internal/security/sign"
)

// sdkEntry is one URL generated by the ImageKit SDKs
// (testdata/sdk/generate.ts).
type sdkEntry struct {
	Name     string `json:"name"`
	Endpoint string `json:"endpoint"`
	Src      string `json:"src"`
	Position string `json:"position"`
	Signed   bool   `json:"signed"`
	URL      string `json:"url"`
}

func loadCorpus(tb testing.TB) []sdkEntry {
	tb.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", "sdk", "corpus.json"))
	if err != nil {
		tb.Fatal(err)
	}
	var corpus []sdkEntry
	if err := json.Unmarshal(b, &corpus); err != nil {
		tb.Fatal(err)
	}
	return corpus
}

// sdkCase turns a corpus URL into a test case for the "endpoint" config,
// which is bound like a host mount whose URL endpoint path is /demo.
func sdkCase(tb testing.TB, e *sdkEntry) testCase {
	tb.Helper()
	u, err := url.Parse(e.URL)
	if err != nil {
		tb.Fatalf("%s: %v", e.Name, err)
	}
	return testCase{name: e.Name, cfg: "endpoint", path: u.EscapedPath(), query: u.RawQuery}
}

// TestSDKCorpus parses URLs built by the official ImageKit SDKs; the
// expected requests are in golden/sdk.json. Every URL keeps its source,
// and every signed URL verifies with the generator's key (the expired one
// is 404).
func TestSDKCorpus(t *testing.T) {
	t.Parallel()
	corpus := loadCorpus(t)
	if len(corpus) < 60 {
		t.Fatalf("corpus has %d entries, want >= 60", len(corpus))
	}
	cases := make([]testCase, 0, len(corpus))
	for i := range corpus {
		cases = append(cases, sdkCase(t, &corpus[i]))
	}
	runGolden(t, "sdk", cases)

	for i := range corpus {
		e := &corpus[i]
		res, err := parseCase(t, sdkCase(t, e))
		if e.Name == "expired" {
			if errs.KindOf(err) != errs.KindExpired {
				t.Errorf("%s: %v, want expired", e.Name, err)
			}
			continue
		}
		if err != nil {
			t.Errorf("%s: %v", e.Name, err)
			continue
		}
		want := strings.TrimPrefix((&url.URL{Path: e.Src}).EscapedPath(), "/")
		if res.SourceString != want {
			t.Errorf("%s: source %q, want %q", e.Name, res.SourceString, want)
		}
		if e.Signed != (res.Signature == sign.Verified) {
			t.Errorf("%s: signature %v, signed %v", e.Name, res.Signature, e.Signed)
		}
	}
}

// TestSDKSignatureTampering flips every part of the signed corpus URLs.
func TestSDKSignatureTampering(t *testing.T) {
	t.Parallel()
	for _, e := range loadCorpus(t) {
		if !e.Signed || e.Name == "expired" {
			continue
		}
		tc := sdkCase(t, &e)
		for _, bad := range []testCase{
			{cfg: tc.cfg, path: tc.path + "x", query: tc.query},
			{cfg: tc.cfg, path: tc.path, query: "a=1&" + tc.query},
			{cfg: tc.cfg, path: tc.path, query: strings.Replace(tc.query, "ik-s=", "ik-s=0", 1)},
			{cfg: tc.cfg, path: tc.path, query: strings.Replace(tc.query, "ik-t=18", "ik-t=19", 1)},
		} {
			if bad.query == tc.query && bad.path == tc.path {
				continue
			}
			_, err := parseCase(t, bad)
			if errs.KindOf(err) != errs.KindUnauthorized {
				t.Errorf("%s: tampered %q?%q: %v, want unauthorized", e.Name, bad.path, bad.query, err)
			}
		}
	}
}
